#define CG3_CGAL_AABBTREE3_CPP "aabb_tree3.cpp"
#include CG3_CGAL_AABBTREE3_CPP
#undef CG3_CGAL_AABBTREE3_CPP
#endif

#endif // CG3_CGAL_AABBTREE3_H

